insert into codex_blocks (unit_id, ord, block_type, payload, source_ref, reviewed_at, reviewed_by)
values
  ('0a7c8ba4d14bb398', 1, 'lead', '{"text": "The basic tradeoff is whether the added fees typically involved in hedge fund investing produce sufficient additional alpha and diversification to justify them. This is an ongoing industry debate, and the exam expects you to be able to argue either side."}'::jsonb, 'CFA 2026 L2 V8/LM4', now(), 'authored'),
  ('0a7c8ba4d14bb398', 2, 'table_compare', '{"headers": ["The case for", "The case against"], "rows": [["Access to the very best investment talent, able to navigate a wider universe of markets", "High fee levels"], ["Alpha produced in down markets is hard to source elsewhere", "Complex offering memorandum documentation that limited partners must understand"], ["Diversification from strategies not dependent on market beta", "Lack of full underlying investment transparency and attribution"], ["Ability to express short views unavailable to long-only vehicles", "Higher cost allocations for establishing and maintaining fund structures"], ["Wider opportunity set including illiquid and esoteric instruments", "Longer-lived commitment periods with limited redemption availability"]]}'::jsonb, 'CFA 2026 L2 V8/LM4', now(), 'authored'),
  ('0a7c8ba4d14bb398', 3, 'key', '{"paras": ["Carry this framing through the module: some hedge fund strategies have higher portfolio <strong>diversification</strong> benefits, while others are simply <strong>return enhancers</strong>. Long/short equity and event-driven strategies may carry less beta than a long-only allocation, but the higher fees make that an expensive form of embedded beta. Managed futures and global macro introduce genuine asset class diversification, at the cost of higher volatility. Relative value volatility and long volatility manage tail risk, at the cost of return drag in normal periods."]}'::jsonb, 'CFA 2026 L2 V8/LM4', now(), 'authored'),
  ('0a7c8ba4d14bb398', 4, 'prose', '{"text": "Each strategy area introduces its own portfolio risks. Arbitrage-oriented strategies use significant leverage to reach meaningful return objectives, which can be dangerous to limited partners during market stress. Many strategies amplify their asset base through margin, highly levered derivatives, and other leveraged approaches."}'::jsonb, 'CFA 2026 L2 V8/LM4', now(), 'authored'),
  ('0a7c8ba4d14bb398', 5, 'heading_2', '{"text": "Liquid alternatives"}'::jsonb, 'CFA 2026 L2 V8/LM4', now(), 'authored'),
  ('0a7c8ba4d14bb398', 6, 'prose', '{"text": "Over the past decade, traditional limited partnership formats have been supplemented by liquid alts: mutual fund, closed-end fund, and ETF vehicles investing in hedge fund-like strategies. They are meant to provide daily liquidity, transparency, and lower fees to a wider investor base."}'::jsonb, 'CFA 2026 L2 V8/LM4', now(), 'authored'),
  ('0a7c8ba4d14bb398', 7, 'trap', '{"paras": ["Empirical evidence shows liquid alts <strong>significantly underperform</strong> similar strategy hedge funds. This suggests traditional hedge funds may benefit from an illiquidity premium that cannot easily be transported into a mutual fund format. Regulatory criteria also restrict these structures from using highly risky, illiquid strategies."]}'::jsonb, 'CFA 2026 L2 V8/LM4', now(), 'authored'),
  ('0a7c8ba4d14bb398', 8, 'heading_2', '{"text": "The six categories"}'::jsonb, 'CFA 2026 L2 V8/LM4', now(), 'authored'),
  ('0a7c8ba4d14bb398', 9, 'table_compare', '{"headers": ["Category", "Approach and characteristic risk", "Strategies covered"], "rows": [["Equity", "Primarily equity and equity-related instruments. The size and sign of equity market exposure dictates classification.", "Long/short equity, dedicated short bias, equity market neutral"], ["Event-driven", "Corporate events as the return catalyst", "Merger arbitrage, distressed securities"], ["Relative value", "Relative valuation between two or more securities. Exposed to credit and liquidity risk, since the valuation differences exploited often arise from exactly those differences.", "Fixed-income arbitrage, convertible bond arbitrage"], ["Opportunistic", "Top-down, multi-asset, often macro-oriented. Risks depend on the opportunity set and vary across time and asset classes.", "Global macro, managed futures"], ["Specialist", "Niche opportunities requiring specialised skill. Exposed to unique risks from particular sectors, niche securities, or esoteric instruments.", "Volatility strategies, reinsurance"], ["Multi-manager", "Building a portfolio of diversified strategies and dynamically reallocating", "Multi-strategy funds, funds-of-funds"]]}'::jsonb, 'CFA 2026 L2 V8/LM4', now(), 'authored');
insert into codex_blocks (unit_id, ord, block_type, payload, source_ref, reviewed_at, reviewed_by)
values
  ('0b751e2edaedb6e1', 1, 'heading_2', '{"text": "Long/short equity"}'::jsonb, 'CFA 2026 L2 V8/LM4', now(), 'authored'),
  ('0b751e2edaedb6e1', 2, 'prose', '{"text": "Holds both long and short positions, typically resulting in more hedged, less volatile portfolios. Alpha derives from the wide variety of equity investments available globally combined with astute long and short stock picking. Styles are diverse: value and growth, large and small cap, discretionary and quantitative, and industry specialised."}'::jsonb, 'CFA 2026 L2 V8/LM4', now(), 'authored'),
  ('0b751e2edaedb6e1', 3, 'table_data', '{"headers": ["Exposure measure", "Typical range"], "rows": [["Net long", "40% to 60%"], ["Gross long", "70% to 90%"], ["Gross short", "20% to 50%"], ["Target return", "Roughly equivalent to a long-only approach"], ["Target standard deviation", "About 50% lower than long-only"]], "aligns": ["", "num"]}'::jsonb, 'CFA 2026 L2 V8/LM4', now(), 'authored'),
  ('0b751e2edaedb6e1', 4, 'prose', '{"text": "Market exposure is the net of <strong>beta-adjusted</strong> long and short exposures. With many strong sells and a relatively large short position, a manager could run net short for brief periods. Many managers are sector specialists, designing funds around their industry expertise and analysing situations from both top-down and bottom-up perspectives."}'::jsonb, 'CFA 2026 L2 V8/LM4', now(), 'authored'),
  ('0b751e2edaedb6e1', 5, 'list_bullet', '{"items": ["Some managers use index-based short hedges to reduce market risk, but most search for single-name shorts for portfolio alpha and added absolute return.", "Some add alpha by timing portfolio beta tilt, but <strong>evidence suggests most do this poorly</strong>.", "Leverage is <strong>variable</strong>: the more market-neutral or quantitative the approach, the more levered the application tends to be.", "Suitable for both limited partnership and mutual fund vehicles."]}'::jsonb, 'CFA 2026 L2 V8/LM4', now(), 'authored'),
  ('0b751e2edaedb6e1', 6, 'heading_2', '{"text": "Dedicated short selling and short-biased"}'::jsonb, 'CFA 2026 L2 V8/LM4', now(), 'authored'),
  ('0b751e2edaedb6e1', 7, 'table_compare', '{"headers": ["", "Dedicated short sellers", "Short-biased managers"], "rows": [["Exposure", "Short side only, though beta may be moderated by holding cash", "Good short-side stock picking, moderated with value-oriented or index long exposure and cash"], ["Typical positioning", "60% to 120% short at all times", "Around 30% to 60% net short"], ["Focus", "Single equity stock picking, not index shorting", "Single equity stock picking, not index shorting"]]}'::jsonb, 'CFA 2026 L2 V8/LM4', now(), 'authored'),
  ('0b751e2edaedb6e1', 8, 'prose', '{"text": "Managers take a bottom-up approach, scanning the universe of potential sell targets for companies whose shares are most likely to decline substantially: inherently flawed business models, unsustainable levels of leverage, and similar."}'::jsonb, 'CFA 2026 L2 V8/LM4', now(), 'authored'),
  ('0b751e2edaedb6e1', 9, 'list_bullet', '{"items": ["Return goals are <strong>lower</strong> than most other strategies, but with a negative correlation benefit. More volatile than a typical long/short fund, given short beta exposure.", "Leverage usage is <strong>low</strong> — there is sufficient natural volatility that managers do not need to add much.", "Best handled in a limited partnership, because of the difficult operational aspects of short selling.", "Historic returns have been lumpy and generally disappointing."]}'::jsonb, 'CFA 2026 L2 V8/LM4', now(), 'authored'),
  ('0b751e2edaedb6e1', 10, 'trap', '{"paras": ["Benchmarking is genuinely difficult because so few managers exist, making an acceptably diverse index hard to construct. The Lipper Dedicated Short-Bias Index includes just four managers. Some investors instead compare returns to the inverse of a related stock index."]}'::jsonb, 'CFA 2026 L2 V8/LM4', now(), 'authored'),
  ('0b751e2edaedb6e1', 11, 'heading_2', '{"text": "Equity market neutral"}'::jsonb, 'CFA 2026 L2 V8/LM4', now(), 'authored'),
  ('0b751e2edaedb6e1', 12, 'prose', '{"text": "Holds balanced long and short exposures to maintain zero or near-zero net exposure to the equity market and to factors such as sector and market capitalisation. Managers then focus on pairs of long and short securities whose prices are out of historical alignment and expected to mean revert."}'::jsonb, 'CFA 2026 L2 V8/LM4', now(), 'authored'),
  ('0b751e2edaedb6e1', 13, 'list_bullet', '{"items": ["Relatively modest return profiles, with high diversification and liquidity and lower standard deviation than many strategies across normal market conditions.", "Many managers are purely <strong>quantitative</strong> rather than discretionary.", "Time horizons are <strong>shorter</strong> than other strategies with more active trading, reflecting the mean-reversion orientation.", "Leverage is <strong>high</strong>. Since many beta risks are hedged away, it is generally deemed acceptable to apply higher leverage while striving for meaningful return targets.", "That leverage typically breaches mutual fund regulatory limits, so limited partnerships are preferred."]}'::jsonb, 'CFA 2026 L2 V8/LM4', now(), 'authored'),
  ('0b751e2edaedb6e1', 14, 'heading_3', '{"text": "Four steps of portfolio construction"}'::jsonb, 'CFA 2026 L2 V8/LM4', now(), 'authored'),
  ('0b751e2edaedb6e1', 15, 'list_ordered', '{"items": ["Evaluate the investment universe, including only tradable securities with sufficient liquidity and adequate short-selling potential.", "Analyse securities for buy and sell candidates.", "Construct the portfolio with offsetting long and short exposures.", "Manage and rebalance to maintain neutrality as prices move."]}'::jsonb, 'CFA 2026 L2 V8/LM4', now(), 'authored'),
  ('0b751e2edaedb6e1', 16, 'key', '{"paras": ["Equity market neutral takes advantage of idiosyncratic short-term mispricing between securities whose prices should otherwise be co-integrated. Unlike many strategies, its sources of return and alpha <strong>do not require accepting beta risk</strong>, which makes it especially attractive during periods of market vulnerability and weakness."]}'::jsonb, 'CFA 2026 L2 V8/LM4', now(), 'authored');
insert into codex_blocks (unit_id, ord, block_type, payload, source_ref, reviewed_at, reviewed_by)
values
  ('6917813b77326d22', 1, 'heading_2', '{"text": "Merger arbitrage"}'::jsonb, 'CFA 2026 L2 V8/LM4', now(), 'authored'),
  ('6917813b77326d22', 2, 'prose', '{"text": "Typically established using common equities, though preferred stock, senior and junior debt, convertible securities, options, and other derivatives may be used for positioning and hedging."}'::jsonb, 'CFA 2026 L2 V8/LM4', now(), 'authored'),
  ('6917813b77326d22', 3, 'key', '{"paras": ["Merger arbitrage delivers <strong>defined gains from idiosyncratic single-security takeover situations, with occasional downside shocks when deals unexpectedly fail</strong>. Its return profile is similar to a <strong>bond plus a short put option</strong>."]}'::jsonb, 'CFA 2026 L2 V8/LM4', now(), 'authored'),
  ('6917813b77326d22', 4, 'prose', '{"text": "The analogy repays attention. Like a bond, the strategy earns a modest predictable spread if nothing goes wrong. Like a short put, it suffers sharply in the bad state. And critically, deals are more likely to fail in market stress periods, so the strategy carries market sensitivity and left-tail risk attributes despite its apparently idiosyncratic nature."}'::jsonb, 'CFA 2026 L2 V8/LM4', now(), 'authored'),
  ('6917813b77326d22', 5, 'heading_3', '{"text": "Where spreads widen"}'::jsonb, 'CFA 2026 L2 V8/LM4', now(), 'authored'),
  ('6917813b77326d22', 6, 'list_bullet', '{"items": ["<strong>Cross-border M&amp;A</strong> usually involves two sets of governmental approvals.", "<strong>Vertical integration</strong> deals often face antitrust scrutiny.", "<strong>Hostile takeovers</strong> carry lower completion probability. Some managers invest only in friendly deals at relatively tight spreads; others embrace riskier hostile situations at wider spreads, sometimes expecting a higher bid from a white knight."]}'::jsonb, 'CFA 2026 L2 V8/LM4', now(), 'authored'),
  ('6917813b77326d22', 7, 'list_bullet', '{"items": ["Relatively high Sharpe ratios with typically low double-digit returns and mid-single-digit standard deviation, depending on leverage applied — but with left-tail risk beneath an otherwise steady return profile.", "Leverage is <strong>moderate to high</strong>: managers typically apply 3 to 5 times.", "Limited partnership preferred, though some low-leverage, low-volatility liquid alts versions exist."]}'::jsonb, 'CFA 2026 L2 V8/LM4', now(), 'authored'),
  ('6917813b77326d22', 8, 'worked', '{"title": "The asymmetry in a single trade", "blocks": [{"text": "Company A offers to acquire Company B for $50 per share in cash. Company B trades at $47.50 after announcement. Expected completion in four months. Pre-announcement price was $38.", "kind": "prose"}, {"text": "The upside if the deal completes", "kind": "step"}, {"expr": "Spread = ($50.00 − $47.50) / $47.50 = 5.26% over four months", "kind": "formula"}, {"expr": "Annualised = 5.26% × 3 = 15.8%", "kind": "formula"}, {"text": "At 4× leverage, that approaches 63% before financing costs.", "kind": "prose"}, {"text": "The downside if the deal breaks", "kind": "step"}, {"expr": "Loss = ($38.00 − $47.50) / $47.50 = −20% unlevered", "kind": "formula"}, {"text": "At the same 4× leverage the levered loss is catastrophic. A modest high-probability gain against a large low-probability loss, amplified by borrowing — and the loss arrives precisely when the rest of the portfolio is also suffering.", "kind": "prose"}]}'::jsonb, 'CFA 2026 L2 V8/LM4', now(), 'authored'),
  ('6917813b77326d22', 9, 'heading_2', '{"text": "Distressed securities"}'::jsonb, 'CFA 2026 L2 V8/LM4', now(), 'authored'),
  ('6917813b77326d22', 10, 'prose', '{"text": "Focuses on firms either in bankruptcy, facing bankruptcy, or under financial stress. Outright shorts or hedged positions are possible, but the strategy is usually <strong>long-biased</strong>. It is subject to security-specific outcomes but still affected by the health of the macro economy."}'::jsonb, 'CFA 2026 L2 V8/LM4', now(), 'authored'),
  ('6917813b77326d22', 11, 'list_bullet', '{"items": ["Return profile is at the <strong>higher end</strong> of event-driven strategies, but with more variability.", "Entails relatively high <strong>illiquidity</strong>, especially with a concentrated activist approach. Pricing may involve <strong>mark-to-model with return smoothing</strong>.", "Ultimate results are generally <strong>binary</strong>: either very good or very bad.", "Leverage is <strong>moderate to low</strong>, typically 1.2 to 1.7 times NAV invested, with some nominal leverage from derivatives hedging.", "Long lock-ups are common — for instance, no redemptions permitted for the first two years."]}'::jsonb, 'CFA 2026 L2 V8/LM4', now(), 'authored'),
  ('6917813b77326d22', 12, 'key', '{"paras": ["Returns tend to be lumpy and somewhat cyclical. Distressed investing is particularly attractive <strong>in the early stages of an economic recovery after a period of market dislocation</strong>. Alpha tends to be idiosyncratic, and the strategy capitalises on information inefficiencies and on the structural inability of traditional managers to hold such securities — which forces selling regardless of value."]}'::jsonb, 'CFA 2026 L2 V8/LM4', now(), 'authored'),
  ('6917813b77326d22', 13, 'trap', '{"paras": ["Note that leverage runs <em>opposite</em> to the arbitrage strategies. Distressed positions are inherently volatile and long-biased, so managers use modest leverage. Hedged arbitrage strategies use high leverage. Leverage in hedge funds is inversely related to the volatility of the underlying positions, not a free choice."]}'::jsonb, 'CFA 2026 L2 V8/LM4', now(), 'authored');
insert into codex_blocks (unit_id, ord, block_type, payload, source_ref, reviewed_at, reviewed_by)
values
  ('20948c8daf3089c3', 1, 'heading_2', '{"text": "Fixed-income arbitrage"}'::jsonb, 'CFA 2026 L2 V8/LM4', now(), 'authored'),
  ('20948c8daf3089c3', 2, 'prose', '{"text": "The risk and return profile derives from the high correlations found across different securities, the yield spread pick-up to be captured, and the sheer number and diversity of debt securities across markets with different credit quality and convexity aspects in their pricing. Structured products built around debt securities add complexity that may result in mispricing opportunities."}'::jsonb, 'CFA 2026 L2 V8/LM4', now(), 'authored'),
  ('20948c8daf3089c3', 3, 'key', '{"paras": ["<strong>Liquidity and opportunity move in opposite directions.</strong> Yield curve and carry trades within the US government universe tend to be very liquid but typically have the fewest mispricing opportunities. Liquidity for relative value positions generally decreases in other sovereign markets, in mortgage-related markets, and especially across corporate debt markets."]}'::jsonb, 'CFA 2026 L2 V8/LM4', now(), 'authored'),
  ('20948c8daf3089c3', 4, 'heading_3', '{"text": "Leverage and the haircut mechanism"}'::jsonb, 'CFA 2026 L2 V8/LM4', now(), 'authored'),
  ('20948c8daf3089c3', 5, 'list_bullet', '{"items": ["Leverage usage is <strong>high</strong>, but availability typically diminishes with product complexity.", "Prime brokers offer collateralised repurchase agreements with associated leverage <strong>haircuts</strong>, depending on the securities traded.", "The haircut is the prime broker''s cushion against market volatility and illiquidity should posted collateral need to be liquidated."]}'::jsonb, 'CFA 2026 L2 V8/LM4', now(), 'authored'),
  ('20948c8daf3089c3', 6, 'trap', '{"paras": ["The haircut is a procyclical amplifier. When markets turn volatile, haircuts rise, forcing deleveraging exactly when spreads are widening and positions look most attractive. This is the mechanism behind most fixed-income arbitrage failures."]}'::jsonb, 'CFA 2026 L2 V8/LM4', now(), 'authored'),
  ('20948c8daf3089c3', 7, 'heading_2', '{"text": "Convertible bond arbitrage"}'::jsonb, 'CFA 2026 L2 V8/LM4', now(), 'authored'),
  ('20948c8daf3089c3', 8, 'prose', '{"text": "A convertible bond embeds a call option on the issuer''s equity, and that embedded optionality has historically been a <strong>structurally cheap source of implied volatility</strong>, because convertible issuance is driven by corporate financing needs rather than option market pricing."}'::jsonb, 'CFA 2026 L2 V8/LM4', now(), 'authored'),
  ('20948c8daf3089c3', 9, 'prose', '{"text": "Managers extract that cheapness by <strong>delta hedging and gamma trading</strong> short equity hedges against long convertible holdings."}'::jsonb, 'CFA 2026 L2 V8/LM4', now(), 'authored'),
  ('20948c8daf3089c3', 10, 'worked', '{"title": "Why the delta-hedged position is price-neutral", "blocks": [{"text": "Long stock exposure via a convertible bond at a €23 conversion price, hedged with a short equity position established at €28.", "kind": "prose"}, {"headers": ["New share price", "Profit on long via convertible", "Profit on short at €28", "Total"], "rows": [["€26", "€3", "€2", "€5"], ["€28", "€5", "€0", "€5"], ["€34", "€11", "−€6", "€5"]], "aligns": ["num", "num", "num", "num"], "kind": "table"}, {"text": "Long profit = new share price − conversion price. Short profit = current share price − new share price.", "kind": "prose"}, {"text": "Where the convertible''s current price sits near conversion value, the combination of a long convertible and short equity delta exposure means profit and loss is the <em>same</em> for small equity moves in either direction. The return comes from volatility, not direction.", "kind": "prose"}], "answer": "Total profit is €5 regardless of where the share price lands"}'::jsonb, 'CFA 2026 L2 V8/LM4', now(), 'authored'),
  ('20948c8daf3089c3', 11, 'heading_3', '{"text": "Positioning and liquidity"}'::jsonb, 'CFA 2026 L2 V8/LM4', now(), 'authored'),
  ('20948c8daf3089c3', 12, 'list_bullet', '{"items": ["Managers typically run portfolios at <strong>300% long against 200% short</strong>. The lower short exposure is a function of the delta-adjusted equity exposure needed to balance the long convertible.", "Liquidity issues surface two ways: convertibles are naturally less liquid given relatively small issue sizes and inherent complexity; and the availability and cost of borrowing the underlying equity for short selling can constrain the trade.", "Leverage is <strong>high</strong>, because many legs are needed — short sale, CDS transaction, interest rate hedge — to extract a modest ultimate gain from delta hedging."]}'::jsonb, 'CFA 2026 L2 V8/LM4', now(), 'authored'),
  ('20948c8daf3089c3', 13, 'table_compare', '{"headers": ["Works best during", "Fares poorly during"], "rows": [["High convertible issuance", "Acute credit weakness"], ["Moderate volatility", "General illiquidity"], ["Reasonable market liquidity", "Supply and demand imbalances unduly affecting convertible pricing"]]}'::jsonb, 'CFA 2026 L2 V8/LM4', now(), 'authored'),
  ('20948c8daf3089c3', 14, 'prose', '{"text": "Convertible bond arbitrage is a core hedge fund strategy area run within many multi-strategy funds alongside long/short equity, merger arbitrage, and other event-driven distressed strategies."}'::jsonb, 'CFA 2026 L2 V8/LM4', now(), 'authored');
insert into codex_blocks (unit_id, ord, block_type, payload, source_ref, reviewed_at, reviewed_by)
values
  ('5331e2ba7a0bfb5d', 1, 'lead', '{"text": "Both global macro and managed futures are highly liquid, but they differ in how discretion is applied and in how crowded their execution has become."}'::jsonb, 'CFA 2026 L2 V8/LM4', now(), 'authored'),
  ('5331e2ba7a0bfb5d', 2, 'table_compare', '{"headers": ["", "Managed futures", "Global macro"], "rows": [["Implementation", "More <strong>systematic</strong>", "Generally more <strong>discretionary</strong> in applying models and tools"], ["Crowding", "Some crowding and execution slippage as AUM has grown rapidly", "Less significant crowding, being more heterogeneous in approach"], ["Stress period behaviour", "Positive <strong>right-tail skewness</strong>, very useful for diversification", "Similar diversification, but more heterogeneous outcomes"], ["Characteristic failure", "Whipsaw in ranging markets", "Can be early and overly anticipatory in positioning"]]}'::jsonb, 'CFA 2026 L2 V8/LM4', now(), 'authored'),
  ('5331e2ba7a0bfb5d', 3, 'key', '{"paras": ["The positive right-tail skewness of managed futures in stress periods is the strategy''s central portfolio argument. Trend-following systems tend already to be positioned short risk assets by the time a crisis is underway, so they gain precisely when equity portfolios are losing."]}'::jsonb, 'CFA 2026 L2 V8/LM4', now(), 'authored'),
  ('5331e2ba7a0bfb5d', 4, 'prose', '{"text": "Despite that positive skewness, both are somewhat cyclical and sit at the more volatile end of the hedge fund spectrum, with <strong>volatility positively related to the strategy''s time horizon</strong> — longer-term trend systems are more volatile than short-term ones."}'::jsonb, 'CFA 2026 L2 V8/LM4', now(), 'authored'),
  ('5331e2ba7a0bfb5d', 5, 'heading_3', '{"text": "Leverage"}'::jsonb, 'CFA 2026 L2 V8/LM4', now(), 'authored'),
  ('5331e2ba7a0bfb5d', 6, 'list_bullet', '{"items": ["<strong>High</strong>, but embedded in the futures contracts rather than borrowed.", "Notional amounts of <strong>6 to 7 times fund assets</strong> can be controlled with initial margin-to-equity of just 10% to 20%.", "Individual futures margin levels are a function of the volatility of the underlying assets.", "Active use of options by many global macro managers adds natural leverage and positive convexity."]}'::jsonb, 'CFA 2026 L2 V8/LM4', now(), 'authored');
insert into codex_blocks (unit_id, ord, block_type, payload, source_ref, reviewed_at, reviewed_by)
values
  ('3ed167ac92f93435', 1, 'heading_2', '{"text": "Volatility trading"}'::jsonb, 'CFA 2026 L2 V8/LM4', now(), 'authored'),
  ('3ed167ac92f93435', 2, 'table_compare', '{"headers": ["Posture", "Payoff", "When it works"], "rows": [["Long volatility", "Positive convexity, particularly useful for hedging", "Market dislocations. Carries premium drag in calm periods."], ["Short volatility", "Option premium sellers extract steadier returns", "Normal market environments. Severe losses in dislocations."], ["Relative value volatility", "Trades volatility differentials across geographies and asset classes", "A useful source of portfolio return alpha independent of direction"]]}'::jsonb, 'CFA 2026 L2 V8/LM4', now(), 'authored'),
  ('3ed167ac92f93435', 3, 'heading_3', '{"text": "Four implementation paths"}'::jsonb, 'CFA 2026 L2 V8/LM4', now(), 'authored'),
  ('3ed167ac92f93435', 4, 'list_ordered', '{"items": ["<strong>Exchange-traded options</strong> — generally liquid, but with longest tenors of about two years and liquidity decreasing as tenor increases.", "<strong>OTC options</strong> — tenor and strike prices can be customised, extending expiry beyond what exchanges offer. Less liquid and less fungible between counterparties.", "<strong>VIX futures and options on VIX futures</strong> — express a pure volatility view without constant delta hedging of an equity put or call to isolate volatility exposure. Very liquid.", "<strong>OTC volatility or variance swaps</strong> — forward contracts on future realised volatility or variance. Both give <em>pure</em> exposure to volatility alone, unlike standardised options where volatility exposure depends on the underlying price and must be extracted by delta hedging."]}'::jsonb, 'CFA 2026 L2 V8/LM4', now(), 'authored'),
  ('3ed167ac92f93435', 5, 'prose', '{"text": "On leverage, the natural convexity of volatility instruments means outsized gains may be earned with very little up-front risk. Notional values appear nominally levered, but the asymmetric nature of long optionality is an attractive aspect of the strategy. Volatility trading is niche and difficult to benchmark: the CBOE Eurekahedge indexes contain 15, 5, 11, and 11 managers respectively for long volatility, short volatility, relative value, and tail risk."}'::jsonb, 'CFA 2026 L2 V8/LM4', now(), 'authored'),
  ('3ed167ac92f93435', 6, 'heading_2', '{"text": "Reinsurance and life settlements"}'::jsonb, 'CFA 2026 L2 V8/LM4', now(), 'authored'),
  ('3ed167ac92f93435', 7, 'prose', '{"text": "Insurance contracts pay the policyholder or beneficiaries on occurrence of a specific insured event, in exchange for a stream of premiums. The market encompasses highly specific, non-standardised contracts, so they are generally illiquid and difficult to trade after initiation."}'::jsonb, 'CFA 2026 L2 V8/LM4', now(), 'authored'),
  ('3ed167ac92f93435', 8, 'prose', '{"text": "The secondary market has grown substantially. Policyholders who no longer need whole or universal life cover can surrender to the original issuer, but increasingly find that third-party brokers pay <strong>higher cash values, significantly above surrender value</strong>. Those brokers then offer the policies as investments to hedge funds. For insurance companies, the reinsurance market allows risk transfer, capital management, and solvency management. For hedge funds, it offers a source of <strong>uncorrelated return alpha</strong>."}'::jsonb, 'CFA 2026 L2 V8/LM4', now(), 'authored'),
  ('3ed167ac92f93435', 9, 'heading_3', '{"text": "What a life settlements manager looks for"}'::jsonb, 'CFA 2026 L2 V8/LM4', now(), 'authored'),
  ('3ed167ac92f93435', 10, 'list_ordered', '{"items": ["The <strong>surrender value</strong> offered to the insured individual is relatively <strong>low</strong>, so the policy can be purchased at a lower price.", "The ongoing <strong>premium payments</strong> to keep the policy active are also relatively <strong>low</strong>.", "The probability that the designated insured person dies <strong>earlier</strong> than standard actuarial methods predict is relatively <strong>high</strong>, meaning cash outflows for premiums will be less than predicted."]}'::jsonb, 'CFA 2026 L2 V8/LM4', now(), 'authored'),
  ('3ed167ac92f93435', 11, 'prose', '{"text": "Valuation requires detailed biometric analysis of the individual policyholder and an understanding of actuarial analysis, so a manager needs that expertise directly or through a trusted actuarial adviser. This is why the strategy sits in the specialist category."}'::jsonb, 'CFA 2026 L2 V8/LM4', now(), 'authored');
insert into codex_blocks (unit_id, ord, block_type, payload, source_ref, reviewed_at, reviewed_by)
values
  ('4b5d0489d84f5b97', 1, 'table_compare', '{"headers": ["", "Funds-of-funds", "Multi-strategy funds"], "rows": [["Structure", "Allocates to external managers", "Runs multiple strategies in-house"], ["Strategy mix", "Potentially <strong>more diverse</strong>", "Constrained to the firm''s capabilities"], ["Transparency", "Less transparent", "<strong>Better</strong> strategy transparency"], ["Tactical reaction time", "Slower", "<strong>Faster</strong> tactical asset allocation"], ["Fee structure", "Added fee layering plus netting risk", "Netting risk handled at strategy level"], ["Leverage", "Gravitate to modest leverage", "Significantly more leverage"], ["Operational risk", "Diversified across firms", "Higher manager-specific operational risk"], ["Performance", "Lower", "Generally outperformed, but with more variance and occasional large losses"], ["Redemption terms", "Similar initial lock-up and redemption periods", "Similar, plus investor-level or fund-level <strong>gates</strong> on maximum quarterly redemptions"]]}'::jsonb, 'CFA 2026 L2 V8/LM4', now(), 'authored'),
  ('4b5d0489d84f5b97', 2, 'heading_2', '{"text": "Netting risk"}'::jsonb, 'CFA 2026 L2 V8/LM4', now(), 'authored'),
  ('4b5d0489d84f5b97', 3, 'key', '{"paras": ["<strong>Netting risk</strong> means FoF investors are responsible for paying performance fees to winning underlying funds while simultaneously suffering return drag from losing underlying funds. In a multi-strategy fund, gains and losses across strategies net against each other before performance fees are calculated."]}'::jsonb, 'CFA 2026 L2 V8/LM4', now(), 'authored'),
  ('4b5d0489d84f5b97', 4, 'worked', '{"title": "Netting risk quantified", "blocks": [{"text": "An investor allocates $100 million equally across two strategies, each charging 20% performance fees. Strategy A gains 20%; Strategy B loses 20%. The portfolio is flat before fees.", "kind": "prose"}, {"headers": ["", "Fund-of-funds", "Multi-strategy"], "rows": [["Gross portfolio result", "$0", "$0"], ["Performance fee on Strategy A (+$10m)", "$2m", "Netted against B"], ["Performance fee on Strategy B (−$10m)", "$0", "Netted"], ["Total performance fee", "$2m", "$0"], ["Net investor result", "−$2m", "$0"]], "aligns": ["", "num", "num"], "total_rows": [3], "kind": "table"}], "answer": "The FoF investor loses $2m on a flat portfolio"}'::jsonb, 'CFA 2026 L2 V8/LM4', now(), 'authored'),
  ('4b5d0489d84f5b97', 5, 'prose', '{"text": "Multi-strategy managers can reallocate capital into different strategy areas more quickly and efficiently than a FoF manager. They have full transparency and a better picture of how different teams'' portfolio risks interact than a FoF could ever achieve, so they can react faster to real-time market impacts, rapidly increasing or decreasing leverage within strategies as perceived riskiness changes."}'::jsonb, 'CFA 2026 L2 V8/LM4', now(), 'authored'),
  ('4b5d0489d84f5b97', 6, 'exam', '{"paras": ["Despite higher leverage making multi-strategy funds somewhat more prone to left-tail blow-up risk in stress periods, the curriculum concludes that better strategy transparency and shorter tactical reaction time make them <strong>overall more resilient than FoFs in preserving capital</strong>. A counterintuitive conclusion, since the leverage point pulls the other way."]}'::jsonb, 'CFA 2026 L2 V8/LM4', now(), 'authored'),
  ('4b5d0489d84f5b97', 7, 'prose', '{"text": "The FoF business model has been under significant pressure since 2008, from fee compression, increased investor interest in passive long-only investing, and the advent of liquid alternatives for retail investors. Multi-strategy funds have grown as institutional investors have come to prefer them."}'::jsonb, 'CFA 2026 L2 V8/LM4', now(), 'authored');
insert into codex_blocks (unit_id, ord, block_type, payload, source_ref, reviewed_at, reviewed_by)
values
  ('93322a0358899d39', 1, 'lead', '{"text": "Hedge fund strategies are dynamic, so a conditional model allows analysis in a specific market environment. It reveals whether exposures that are insignificant during calm periods become significant during turbulent ones."}'::jsonb, 'CFA 2026 L2 V8/LM4', now(), 'authored'),
  ('93322a0358899d39', 2, 'formula', '{"expr": "R<sub>i,t</sub> = α<sub>i</sub> + Σ β<sub>i,k</sub>(Factor<sub>k</sub>)<sub>t</sub> + Σ D<sub>t</sub>β<sub>i,k</sub>(Factor<sub>k</sub>)<sub>t</sub> + ε<sub>i,t</sub>"}'::jsonb, 'CFA 2026 L2 V8/LM4', now(), 'authored'),
  ('93322a0358899d39', 3, 'list_bullet', '{"items": ["β<sub>i,k</sub>(Factor<sub>k</sub>)<sub>t</sub> is exposure to risk factor k during <strong>normal</strong> times.", "D<sub>t</sub>β<sub>i,k</sub>(Factor<sub>k</sub>)<sub>t</sub> is the <strong>incremental</strong> exposure during financial crisis periods, where D<sub>t</sub> is a dummy equal to 1 during crisis (the study uses June 2007 to February 2009) and 0 otherwise.", "Each factor beta represents the expected change in hedge fund returns for a one-unit increase in that risk factor, holding all others constant."]}'::jsonb, 'CFA 2026 L2 V8/LM4', now(), 'authored'),
  ('93322a0358899d39', 4, 'key', '{"paras": ["The dummy variable is the whole point. It lets a single regression estimate <em>different</em> factor exposures in normal and crisis regimes, which an unconditional model cannot do. Unintended adverse risk exposures revealed during the global financial crisis resulted in the demise of literally thousands of hedge funds worldwide."]}'::jsonb, 'CFA 2026 L2 V8/LM4', now(), 'authored'),
  ('93322a0358899d39', 5, 'heading_2', '{"text": "The six base factors"}'::jsonb, 'CFA 2026 L2 V8/LM4', now(), 'authored'),
  ('93322a0358899d39', 6, 'table_compare', '{"headers": ["Factor", "Proxy"], "rows": [["Equity risk (SNP500)", "Monthly total return of the S&amp;P 500 Index, including dividends"], ["Interest rate risk (BOND)", "Monthly return of the Bloomberg Barclays Corporate AA Intermediate Bond Index"], ["Currency risk (USD)", "Monthly return of the US Dollar Index"], ["Commodity risk (CMDTY)", "Monthly total return of the Goldman Sachs Commodity Index"], ["Credit risk (CREDIT)", "Difference between monthly seasoned Baa and Aaa corporate bond yields, per Moody''s"], ["Volatility risk (VIX)", "First difference of the end-of-month CBOE Volatility Index"]]}'::jsonb, 'CFA 2026 L2 V8/LM4', now(), 'authored'),
  ('93322a0358899d39', 7, 'heading_2', '{"text": "Interpreting desired factor exposures"}'::jsonb, 'CFA 2026 L2 V8/LM4', now(), 'authored'),
  ('93322a0358899d39', 8, 'prose', '{"text": "A skilled manager''s exposures should <em>flip sign</em> between regimes. The curriculum sets out what a well-positioned fund looks like in each state."}'::jsonb, 'CFA 2026 L2 V8/LM4', now(), 'authored'),
  ('93322a0358899d39', 9, 'table_compare', '{"headers": ["Period and factor", "Typical market trend", "Desired position", "Exposure", "Rationale"], "rows": [["<strong>Normal</strong> · SNP500", "Equities rising", "Long", "Positive", "Add risk, increase return"], ["Normal · CREDIT", "Spreads flat or narrowing", "Long", "Positive", "Add risk, increase return"], ["Normal · USD", "USD flat or depreciating", "Short", "Negative", "Sells USD to boost returns"], ["Normal · VIX", "Volatility falling", "Short", "Negative", "Sells volatility to boost returns"], ["<strong>Crisis</strong> · DSNP500", "Equities falling sharply", "Short", "Negative", "Reduce risk"], ["Crisis · DCREDIT", "Spreads widening", "Short", "Negative", "Reduce risk"], ["Crisis · DUSD", "USD appreciating", "Long", "Positive", "USD is a haven in crisis"], ["Crisis · DVIX", "Volatility rising", "Long", "Positive", "Negative correlation with equities"]]}'::jsonb, 'CFA 2026 L2 V8/LM4', now(), 'authored'),
  ('93322a0358899d39', 10, 'heading_2', '{"text": "Alpha, omitted factors, and the stepwise process"}'::jsonb, 'CFA 2026 L2 V8/LM4', now(), 'authored'),
  ('93322a0358899d39', 11, 'prose', '{"text": "The portion of returns not explained by the risk factors is attributable to three sources: <strong>alpha</strong>, the manager''s unique investment skill; <strong>omitted factors</strong>; and <strong>random errors</strong>."}'::jsonb, 'CFA 2026 L2 V8/LM4', now(), 'authored'),
  ('93322a0358899d39', 12, 'trap', '{"paras": ["An omitted factor shows up as alpha, and the model cannot distinguish the two. This is the standard critique of hedge fund alpha claims, and a reason never to read a high intercept as skill without further work."]}'::jsonb, 'CFA 2026 L2 V8/LM4', now(), 'authored'),
  ('93322a0358899d39', 13, 'prose', '{"text": "Because the candidate factors are themselves correlated, a four-step stepwise regression is used to build a model less likely to include highly correlated factors and so avoid multicollinearity:"}'::jsonb, 'CFA 2026 L2 V8/LM4', now(), 'authored'),
  ('93322a0358899d39', 14, 'list_ordered', '{"items": ["Identify potentially important risk factors.", "Calculate pairwise correlations across all risk factors. Where two-state conditional models are used, calculate correlations <strong>for both states</strong> separately.", "Eliminate or combine highly correlated factors.", "Estimate the model with the reduced factor set and test significance."]}'::jsonb, 'CFA 2026 L2 V8/LM4', now(), 'authored'),
  ('93322a0358899d39', 15, 'key', '{"paras": ["Step 2 carries the subtlety worth remembering: correlations between risk factors are <strong>not stable across regimes</strong>. Factors that look independent in calm markets often converge in a crisis — exactly when the model most needs to be reliable."]}'::jsonb, 'CFA 2026 L2 V8/LM4', now(), 'authored'),
  ('93322a0358899d39', 16, 'prose', '{"text": "Because hedge funds may invest in illiquid securities, which artificially smooth returns and lower measured standard deviation, analysts should also examine the <strong>autocorrelation</strong> of returns alongside risk and return measures. Serial autocorrelation is a liquidity signal, and the same smoothing problem seen with appraisal-based real estate indexes applies here."}'::jsonb, 'CFA 2026 L2 V8/LM4', now(), 'authored');
insert into codex_blocks (unit_id, ord, block_type, payload, source_ref, reviewed_at, reviewed_by)
values
  ('607d145273daa5f5', 1, 'lead', '{"text": "The final learning outcome asks you to evaluate the impact of an allocation to a hedge fund strategy within a traditional portfolio. The curriculum''s evidence produces a clear and somewhat counterintuitive ranking."}'::jsonb, 'CFA 2026 L2 V8/LM4', now(), 'authored'),
  ('607d145273daa5f5', 2, 'heading_2', '{"text": "The measures used, and why Sharpe alone fails"}'::jsonb, 'CFA 2026 L2 V8/LM4', now(), 'authored'),
  ('607d145273daa5f5', 3, 'table_compare', '{"headers": ["Measure", "What it captures", "Why it matters here"], "rows": [["Mean return", "Average performance", "Necessary but insufficient alone"], ["Standard deviation", "Total volatility", "Penalises upside and downside symmetrically, misrepresenting asymmetric strategies"], ["Sharpe ratio", "Excess return per unit of total volatility", "Standard comparison, but blind to skewness"], ["Sortino ratio", "Excess return per unit of <strong>downside</strong> deviation", "Replaces standard deviation with downside deviation, concentrating on returns below a threshold"], ["Maximum drawdown", "Largest difference between a high-water mark and any subsequent low point", "Captures the tail risk that volatility measures miss"], ["Autocorrelation (rho)", "Serial correlation of returns", "Reveals artificial smoothing from illiquid holdings"]]}'::jsonb, 'CFA 2026 L2 V8/LM4', now(), 'authored'),
  ('607d145273daa5f5', 4, 'trap', '{"paras": ["Merger arbitrage and short volatility strategies produce high Sharpe ratios <em>because</em> their return distributions are negatively skewed. Steady small gains keep measured volatility low while the rare large loss barely registers until it occurs. The Sharpe ratio flatters exactly the strategies whose risk it fails to measure."]}'::jsonb, 'CFA 2026 L2 V8/LM4', now(), 'authored'),
  ('607d145273daa5f5', 5, 'heading_2', '{"text": "What the evidence shows"}'::jsonb, 'CFA 2026 L2 V8/LM4', now(), 'authored'),
  ('607d145273daa5f5', 6, 'prose', '{"text": "The curriculum examines a traditional stock and bond portfolio with a maximum drawdown of <strong>14.42%</strong>, then substitutes a 20% hedge fund allocation to produce a 48/32/20 blend."}'::jsonb, 'CFA 2026 L2 V8/LM4', now(), 'authored'),
  ('607d145273daa5f5', 7, 'table_compare', '{"headers": ["Contribution", "Strategies", "Why"], "rows": [["<strong>Smallest</strong> maximum drawdowns, best risk mitigation", "Global macro, systematic (managed) futures, merger arbitrage, equity market neutral", "The conditional model showed little exposure to equity or credit risk during crisis periods. They also have the lowest serial autocorrelation, signalling good liquidity, so they remain tradable under stress."], ["Lowest standard deviations in the combined portfolio", "Systematic futures (6.94%), FoF macro/systematic and equity market neutral (a little over 7.0%)", "Significant risk-reducing diversification; the same categories that enhance risk-adjusted returns when added to a 60/40 portfolio."], ["<strong>Highest</strong> maximum drawdowns, little risk reduction", "Long/short equity, event-driven and distressed, relative value and convertible arbitrage", "The conditional model showed these hold equity risk, and their credit risk became significant during crisis. Compounded by the binary long-biased nature of distressed and the leverage downsizing and liquidity problems of relative value under stress."]]}'::jsonb, 'CFA 2026 L2 V8/LM4', now(), 'authored'),
  ('607d145273daa5f5', 8, 'key', '{"paras": ["The strategies that help are the ones that are <em>not exposed to the same risks</em> as the traditional portfolio, are relatively opportunistic, and remain <em>liquid during periods of market stress</em>. All three conditions matter. A strategy that is uncorrelated on paper but cannot be traded in a crisis provides no protection when it is needed."]}'::jsonb, 'CFA 2026 L2 V8/LM4', now(), 'authored'),
  ('607d145273daa5f5', 9, 'exam', '{"paras": ["Note the through-line from Section 8. The conditional factor model is not a separate topic from portfolio contribution — it is the <em>explanation</em> for it. Strategies showing crisis-period equity and credit exposure in the regression are precisely those producing large drawdowns in the combined portfolio. Expect a question that requires you to connect the two."]}'::jsonb, 'CFA 2026 L2 V8/LM4', now(), 'authored');
insert into codex_blocks (unit_id, ord, block_type, payload, source_ref, reviewed_at, reviewed_by)
values
  ('4086876c95e9282f', 1, 'heading_2', '{"text": "Master comparison"}'::jsonb, 'CFA 2026 L2 V8/LM4', now(), 'authored'),
  ('4086876c95e9282f', 2, 'table_compare', '{"headers": ["Strategy", "Leverage", "Liquidity", "Principal risk"], "rows": [["Long/short equity", "Variable", "High", "Residual beta; poor beta timing"], ["Dedicated short bias", "Low", "High", "Lumpy, disappointing returns; operational difficulty"], ["Equity market neutral", "High", "High", "Model failure amplified by leverage"], ["Merger arbitrage", "Moderate–high, 3–5×", "Relatively liquid", "Deal break; left-tail risk correlated with stress"], ["Distressed securities", "Low, 1.2–1.7×", "Illiquid", "Binary outcomes; mark-to-model smoothing"], ["Fixed-income arbitrage", "High", "Varies by market", "Rising haircuts forcing procyclical deleveraging"], ["Convertible arbitrage", "High, 300/200", "Constrained", "Credit stress; equity borrow availability"], ["Global macro", "High, embedded", "High", "Early or overly anticipatory positioning"], ["Managed futures", "High, embedded", "High", "Crowding and slippage; whipsaw in ranging markets"], ["Volatility trading", "Convexity-based", "Varies by instrument", "Short vol tail risk; long vol premium drag"], ["Reinsurance and life settlements", "Low", "Illiquid", "Event occurrence; actuarial misjudgement"], ["Funds-of-funds", "Modest", "Poor", "Netting risk; fee layering; slow reaction"], ["Multi-strategy", "High", "Poor, with gates", "Concentrated operational risk; leverage blow-up"]]}'::jsonb, 'CFA 2026 L2 V8/LM4', now(), 'authored'),
  ('4086876c95e9282f', 3, 'heading_2', '{"text": "The leverage principle"}'::jsonb, 'CFA 2026 L2 V8/LM4', now(), 'authored'),
  ('4086876c95e9282f', 4, 'key', '{"paras": ["Leverage in hedge funds is <strong>inversely related to the volatility of the underlying positions</strong>.<br><br>Hedged, low-volatility arbitrage strategies — equity market neutral, fixed-income arbitrage, convertible arbitrage — use <strong>high</strong> leverage to reach meaningful returns.<br><br>Directional, high-volatility strategies — distressed, dedicated short — use <strong>low</strong> leverage, because the positions supply enough volatility unaided."]}'::jsonb, 'CFA 2026 L2 V8/LM4', now(), 'authored'),
  ('4086876c95e9282f', 5, 'heading_2', '{"text": "Ten points for a final pass"}'::jsonb, 'CFA 2026 L2 V8/LM4', now(), 'authored'),
  ('4086876c95e9282f', 6, 'list_ordered', '{"items": ["Six categories: equity, event-driven, relative value, opportunistic, specialist, multi-manager.", "Liquid alts underperform comparable hedge funds, likely because the illiquidity premium cannot be transported into a daily-liquid format.", "Long/short equity runs 40–60% net long, targeting long-only returns at roughly half the volatility.", "Merger arbitrage pays like a bond plus a short put: steady gains with left-tail risk clustering in stress.", "Distressed is long-biased, illiquid, binary, and most attractive early in an economic recovery.", "In fixed-income arbitrage, liquidity and opportunity move in opposite directions, and haircuts force procyclical deleveraging.", "Convertible arbitrage buys structurally cheap implied volatility and delta hedges it, 300% long against 200% short.", "Managed futures are systematic, global macro discretionary; both give positive right-tail skewness in stress.", "Netting risk means FoF investors pay performance fees to winners while suffering drag from losers.", "Strategies that reduce drawdown are those without crisis-period equity or credit exposure, with low autocorrelation, that stay liquid under stress."]}'::jsonb, 'CFA 2026 L2 V8/LM4', now(), 'authored'),
  ('4086876c95e9282f', 7, 'prose', '{"text": "Notes prepared from the CFA Program 2026 Level II curriculum, Volume 8, Learning Module 4. Strategy risk, leverage, and benchmarking characteristics follow the curriculum''s own exhibits; portfolio contribution findings and the conditional factor exposure table are as published."}'::jsonb, 'CFA 2026 L2 V8/LM4', now(), 'authored');
